INSERT INTO public.learning_modules (id, sort_order, title, topic, color, position, material_title, material_content, material_summary) VALUES
  (1, 1, 'Pulau Angka', 'Pengenalan Angka 1-10', 'bg-emerald-500', 'center', 'Mengenal Angka Dasar', 'Angka adalah simbol untuk menghitung. 1 (satu) seperti tiang, 2 (dua) seperti bebek, 3 (tiga) seperti burung terbang.', 'Ingat bentuk visual angka untuk mempermudah hafalan.'),
  (2, 2, 'Lembah Penjumlahan', 'Penjumlahan Sederhana', 'bg-blue-500', 'left', 'Konsep Penjumlahan', 'Penjumlahan artinya menggabungkan. Jika kamu punya 1 apel, lalu diberi 1 apel lagi, kamu punya 2 apel. Simbolnya (+).', 'Gabungkan dua kelompok benda menjadi satu.'),
  (3, 3, 'Gua Pengurangan', 'Pengurangan Dasar', 'bg-purple-500', 'right', 'Konsep Pengurangan', 'Pengurangan artinya mengambil sebagian. Ada 5 burung, terbang 2, sisa 3. Simbolnya (-).', 'Hitung mundur atau ambil benda.'),
  (4, 4, 'Puncak Logika', 'Pola & Urutan', 'bg-orange-500', 'center', 'Mengenal Pola', 'Pola adalah urutan yang berulang. Merah, Biru, Merah, Biru... selanjutnya pasti Merah!', 'Perhatikan pengulangan untuk menebak selanjutnya.'),
  (5, 5, 'Hutan Pengetahuan', 'Ilmu Pengetahuan Alam', 'bg-green-600', 'left', 'Makhluk Hidup', 'Makhluk hidup itu bernapas, makan, dan tumbuh. Contohnya manusia, hewan, dan tumbuhan. Batu dan air adalah benda mati.', 'Bedakan antara benda hidup dan benda mati.'),
  (6, 6, 'Kota Bahasa', 'Bahasa & Kata', 'bg-pink-500', 'right', 'Lawan Kata', 'Lawan kata adalah kata yang maknanya berlawanan. Contoh: Besar lawannya Kecil. Panas lawannya Dingin.', 'Belajar antonim untuk memperkaya kosakata.'),
  (7, 7, 'Samudra Geografi', 'Lingkungan Sosial', 'bg-cyan-500', 'center', 'Mengenal Tempat', 'Sekolah adalah tempat belajar. Pasar tempat jual beli. Rumah Sakit tempat berobat.', 'Pahami fungsi tempat-tempat umum di sekitar kita.'),
  (8, 8, 'Benteng Kesehatan', 'Kesehatan Diri', 'bg-red-500', 'left', 'Menjaga Kebersihan', 'Mandi 2 kali sehari. Sikat gigi sesudah makan dan sebelum tidur. Cuci tangan sebelum makan agar bebas kuman.', 'Kebersihan adalah pangkal kesehatan.'),
  (9, 9, 'Galeri Seni', 'Warna & Bentuk', 'bg-yellow-500', 'right', 'Warna Dasar', 'Warna dasar ada Merah, Kuning, Biru. Campuran Merah dan Kuning jadi Oranye. Campuran Biru dan Kuning jadi Hijau.', 'Eksplorasi percampuran warna dan bentuk benda.'),
  (10, 10, 'Puncak Harapan', 'Pengetahuan Umum', 'bg-indigo-600', 'center', 'Rangkuman Pengetahuan', 'Dalam satu minggu ada 7 hari. Dalam satu tahun ada 12 bulan. Bumi itu bulat.', 'Fakta-fakta dasar tentang dunia kita.')
INSERT INTO public.quiz_questions (module_id, sort_order, question, options, answer)
INSERT INTO public.materials (slug, level, sort_order, title, content) VALUES
  ('m1', 'mudah', 1, 'Bab 1: Pengenalan Angka', 'Angka adalah simbol yang digunakan untuk mewakili bilangan. Dalam matematika dasar, kita mengenal angka 0 hingga 9 sebagai digit dasar. Kombinasi digit ini membentuk bilangan yang lebih besar.'),
  ('m2', 'mudah', 2, 'Bab 2: Penjumlahan Sederhana', 'Penjumlahan adalah proses menggabungkan dua kelompok benda atau angka menjadi satu. Tanda tambah (+) digunakan untuk menunjukkan penjumlahan. Misalnya, 2 apel + 1 apel = 3 apel.'),
  ('m3', 'mudah', 3, 'Bab 3: Mengenal Warna Dasar', 'Warna dasar atau primer adalah warna utama yang tidak bisa dibuat dari campuran warna lain. Tiga warna dasar adalah Merah, Kuning, dan Biru. Mencampur warna ini akan menghasilkan warna baru seperti Hijau atau Ungu.'),
  ('m4', 'mudah', 4, 'Bab 4: Mengenal Huruf Vokal', 'Dalam abjad, terdapat huruf vokal dan konsonan. Huruf vokal terdiri dari A, I, U, E, dan O. Huruf-huruf ini sangat penting karena memberikan bunyi pada setiap kata yang kita ucapkan.'),
  ('m5', 'mudah', 5, 'Bab 5: Bagian Tubuh Kita', 'Tubuh manusia terdiri dari berbagai bagian yang memiliki fungsi khusus. Mata untuk melihat, telinga untuk mendengar, hidung untuk mencium bau, dan kulit untuk meraba. Menjaga kebersihan tubuh sangat penting untuk kesehatan.'),
  ('m6', 'mudah', 6, 'Bab 6: Hewan di Sekitar Kita', 'Hewan dapat dibagi menjadi hewan peliharaan dan hewan liar. Kucing dan anjing adalah contoh hewan peliharaan. Singa dan gajah adalah hewan liar. Setiap hewan memiliki cara bergerak yang berbeda, ada yang berjalan, terbang, atau berenang.'),
  ('m7', 'mudah', 7, 'Bab 7: Siang dan Malam', 'Bumi berputar pada porosnya menyebabkan terjadinya siang dan malam. Saat bagian Bumi menghadap Matahari, kita mengalami siang. Saat membelakangi Matahari, kita mengalami malam yang gelap dan bisa melihat Bulan.'),
  ('m8', 'mudah', 8, 'Bab 8: Pentingnya Air', 'Air adalah sumber kehidupan. Manusia, hewan, dan tumbuhan membutuhkan air untuk bertahan hidup. Kita menggunakan air untuk minum, mandi, dan mencuci. Kita harus hemat air dan tidak boleh membuang sampah ke sungai.'),
  ('m9', 'mudah', 9, 'Bab 9: Mengenal Bentuk Geometri', 'Benda-benda di sekitar kita memiliki bentuk. Ada lingkaran seperti bola, persegi seperti jendela, dan segitiga seperti potongan pizza. Mengenal bentuk membantu kita menggambar dan memahami ruang.'),
  ('m10', 'mudah', 10, 'Bab 10: Keluarga Inti', 'Keluarga inti terdiri dari Ayah, Ibu, dan Anak. Setiap anggota keluarga memiliki peran. Kita harus saling menyayangi dan menghormati orang tua serta rukun dengan saudara.'),
  ('m11', 'mudah', 11, 'Bab 11: Arah Mata Angin', 'Untuk mengetahui arah, kita menggunakan mata angin. Empat arah utama adalah Utara, Selatan, Timur (tempat matahari terbit), dan Barat (tempat matahari terbenam).'),
  ('t1', 'menengah', 1, 'Bab 1: Konsep Perkalian', 'Perkalian adalah penjumlahan berulang. Daripada menjumlahkan 3 + 3 + 3 + 3, kita bisa menulisnya sebagai 3 x 4. Hasilnya adalah 12. Ini membantu menghitung jumlah benda dalam kelompok yang sama dengan cepat.'),
  ('t2', 'menengah', 2, 'Bab 2: Siklus Air (Hidrologi)', 'Air di Bumi tidak pernah habis karena siklus air. Air laut menguap menjadi awan (evaporasi), awan menjadi berat dan turun sebagai hujan (presipitasi), lalu air mengalir kembali ke laut. Proses ini terus berulang.'),
  ('t3', 'menengah', 3, 'Bab 3: Sistem Tata Surya', 'Bumi adalah salah satu planet yang mengelilingi Matahari. Ada 8 planet dalam tata surya kita: Merkurius, Venus, Bumi, Mars, Jupiter, Saturnus, Uranus, dan Neptunus. Matahari adalah bintang pusat tata surya.'),
  ('t4', 'menengah', 4, 'Bab 4: Fotosintesis', 'Tumbuhan memasak makanannya sendiri melalui fotosintesis. Dengan bantuan sinar matahari, air, dan karbon dioksida, daun menghasilkan oksigen dan gula. Oksigen inilah yang kita hirup setiap hari.'),
  ('t5', 'menengah', 5, 'Bab 5: Struktur Kalimat (SPOK)', 'Kalimat yang lengkap biasanya memiliki struktur Subjek (pelaku), Predikat (tindakan), Objek (sasaran), dan Keterangan (waktu/tempat). Contoh: ''Ibu (S) memasak (P) nasi (O) di dapur (K)''.'),
  ('t6', 'menengah', 6, 'Bab 6: Sejarah Kemerdekaan', 'Kemerdekaan adalah hak segala bangsa. Mempelajari sejarah para pahlawan yang berjuang melawan penjajah mengajarkan kita tentang keberanian, pengorbanan, dan cinta tanah air.'),
  ('t7', 'menengah', 7, 'Bab 7: Peta dan Globe', 'Peta adalah gambaran permukaan bumi pada bidang datar, sedangkan Globe adalah tiruan bumi berbentuk bulat. Kita belajar tentang benua, samudra, garis khatulistiwa, dan skala jarak melalui peta.'),
  ('t8', 'menengah', 8, 'Bab 8: Energi Terbarukan', 'Energi terbarukan adalah energi yang tidak akan habis, seperti sinar matahari, angin, dan air. Penggunaan energi ini lebih ramah lingkungan dibandingkan bahan bakar fosil seperti minyak bumi dan batu bara.'),
  ('t9', 'menengah', 9, 'Bab 9: Rantai Makanan', 'Di alam, makhluk hidup saling memakan untuk bertahan hidup. Padi dimakan tikus, tikus dimakan ular, ular dimakan elang. Ini disebut rantai makanan. Jika satu hilang, keseimbangan alam akan terganggu.'),
  ('t10', 'menengah', 10, 'Bab 10: Demokrasi dan Pemilu', 'Demokrasi berarti pemerintahan dari rakyat, oleh rakyat, dan untuk rakyat. Salah satu wujudnya adalah Pemilu, di mana warga negara memilih pemimpin mereka secara bebas dan adil.'),
  ('t11', 'menengah', 11, 'Bab 11: Pecahan Sederhana', 'Pecahan mewakili bagian dari keseluruhan. Jika sebuah pizza dipotong menjadi 4 bagian sama besar, satu potong adalah 1/4 (satu per empat). Angka atas disebut pembilang, angka bawah disebut penyebut.'),
  ('s1', 'sulit', 1, 'Bab 1: Aljabar Linear', 'Aljabar linear mempelajari vektor, ruang vektor, transformasi linear, dan sistem persamaan linear. Konsep ini sangat penting dalam fisika modern, grafika komputer, dan pemrosesan data.'),
  ('s2', 'sulit', 2, 'Bab 2: Teori Relativitas', 'Dikemukakan oleh Einstein, teori ini menjelaskan bahwa ruang dan waktu bukanlah hal yang mutlak, melainkan relatif tergantung pada kecepatan pengamat. E=mc² adalah rumus terkenal yang menghubungkan energi dan massa.'),
  ('s3', 'sulit', 3, 'Bab 3: Genetika dan DNA', 'DNA adalah cetak biru kehidupan yang membawa informasi genetik. Genetika mempelajari bagaimana sifat-sifat fisik dan biologis diwariskan dari orang tua ke anak melalui gen dan kromosom.'),
  ('s4', 'sulit', 4, 'Bab 4: Makroekonomi: Inflasi', 'Inflasi adalah penurunan nilai mata uang yang menyebabkan kenaikan harga barang secara umum. Hal ini dipengaruhi oleh jumlah uang beredar, permintaan pasar, dan biaya produksi. Bank sentral mengatur suku bunga untuk mengendalikannya.'),
  ('s5', 'sulit', 5, 'Bab 5: Kecerdasan Buatan (AI)', 'Artificial Intelligence adalah simulasi kecerdasan manusia oleh mesin. Ini mencakup Machine Learning, di mana komputer belajar dari data tanpa diprogram secara eksplisit. AI digunakan dalam pengenalan wajah, mobil otonom, dan asisten digital.'),
  ('s6', 'sulit', 6, 'Bab 6: Perubahan Iklim Global', 'Pemanasan global disebabkan oleh efek rumah kaca akibat emisi karbon berlebih. Dampaknya mencakup mencairnya es kutub, naiknya permukaan laut, dan cuaca ekstrem. Mitigasi dan adaptasi sangat diperlukan.'),
  ('s7', 'sulit', 7, 'Bab 7: Psikologi Kognitif', 'Cabang psikologi ini mempelajari proses mental internal seperti persepsi, memori, pemecahan masalah, dan bahasa. Memahami bagaimana otak memproses informasi membantu dalam pendidikan dan terapi mental.'),
  ('s8', 'sulit', 8, 'Bab 8: Hukum Termodinamika', 'Hukum fisika yang mengatur energi dan panas. Hukum pertama menyatakan energi tidak dapat diciptakan atau dimusnahkan. Hukum kedua menyatakan entropi (ketidakteraturan) dalam sistem tertutup akan selalu meningkat.'),
  ('s9', 'sulit', 9, 'Bab 9: Revolusi Industri 4.0', 'Era industri yang menggabungkan teknologi otomatisasi dengan pertukaran data siber. Ini mencakup Internet of Things (IoT), Cloud Computing, dan Big Data, yang mengubah cara manusia bekerja dan hidup.'),
  ('s10', 'sulit', 10, 'Bab 10: Sastra dan Simbolisme', 'Dalam sastra tingkat lanjut, penulis menggunakan simbolisme untuk menyampaikan makna tersembunyi. Metafora, alegori, dan ironi digunakan untuk mengkritik sosial atau menggambarkan kondisi psikologis karakter secara mendalam.'),
  ('s11', 'sulit', 11, 'Bab 11: Manajemen Strategis', 'Proses perencanaan, pemantauan, analisis, dan penilaian yang dilakukan organisasi untuk mencapai tujuan jangka panjang. Termasuk analisis SWOT (Strengths, Weaknesses, Opportunities, Threats) untuk keunggulan kompetitif.')
