-- Data awal HopeAI, dihasilkan dari konten yang sebelumnya tertanam di Pathly.tsx dan Flexa.tsx.
-- Aman dijalankan ulang.

ON CONFLICT (id) DO NOTHING;

SELECT setval(pg_get_serial_sequence('public.learning_modules', 'id'), (SELECT max(id) FROM public.learning_modules));

SELECT v.module_id, v.sort_order, v.question, v.options::jsonb, v.answer FROM (VALUES
  (1, 1, 'Angka setelah 2 adalah?', '["1","3","4","5"]', '3'),
  (1, 2, 'Mana yang lebih besar: 5 atau 2?', '["5","2","Sama","0"]', '5'),
  (1, 3, 'Berapa jumlah jari di satu tangan?', '["4","5","6","10"]', '5'),
  (2, 1, '1 + 1 = ?', '["11","2","3","0"]', '2'),
  (2, 2, '2 + 3 = ?', '["5","6","4","1"]', '5'),
  (2, 3, 'Jika Alya punya 2 permen dan Budi memberi 1 lagi, berapa permen Alya?', '["2","3","4","1"]', '3'),
  (3, 1, '5 - 2 = ?', '["3","2","7","5"]', '3'),
  (3, 2, '10 - 5 = ?', '["15","5","0","2"]', '5'),
  (3, 3, 'Ibu membeli 4 telur, pecah 1. Sisa berapa?', '["3","4","5","2"]', '3'),
  (4, 1, '1, 2, 1, 2, ... selanjutnya?', '["1","2","3","0"]', '1'),
  (4, 2, 'A, B, A, B, ... selanjutnya?', '["A","B","C","D"]', 'A'),
  (4, 3, 'Siang, Malam, Siang, ... selanjutnya?', '["Pagi","Malam","Sore","Siang"]', 'Malam'),
  (5, 1, 'Manakah yang merupakan makhluk hidup?', '["Batu","Meja","Kucing","Air"]', 'Kucing'),
  (5, 2, 'Makanan sapi adalah?', '["Daging","Rumput","Nasi","Ikan"]', 'Rumput'),
  (5, 3, 'Matahari terbit di sebelah?', '["Barat","Timur","Utara","Selatan"]', 'Timur'),
  (6, 1, 'Lawan kata dari ''Panas'' adalah?', '["Dingin","Hangat","Api","Terbakar"]', 'Dingin'),
  (6, 2, 'Lawan kata dari ''Besar'' adalah?', '["Raksasa","Kecil","Luas","Tinggi"]', 'Kecil'),
  (6, 3, 'Hewan yang mengeong adalah?', '["Anjing","Ayam","Kucing","Bebek"]', 'Kucing'),
  (7, 1, 'Tempat untuk belajar disebut?', '["Pasar","Sekolah","Bandara","Hotel"]', 'Sekolah'),
  (7, 2, 'Ibu kota negara Indonesia adalah?', '["Bandung","Surabaya","Jakarta","Medan"]', 'Jakarta'),
  (7, 3, 'Lampu lalu lintas warna merah artinya?', '["Jalan","Berhenti","Hati-hati","Ngebut"]', 'Berhenti'),
  (8, 1, 'Kita harus menyikat gigi minimal ... kali sehari.', '["1","2","5","Tidak perlu"]', '2'),
  (8, 2, 'Sebelum makan kita harus?', '["Tidur","Mencuci tangan","Bermain","Lari"]', 'Mencuci tangan'),
  (8, 3, 'Makanan yang sehat mengandung?', '["Banyak gula","Vitamin","Pengawet","Pewarna"]', 'Vitamin'),
  (9, 1, 'Warna langit yang cerah adalah?', '["Hijau","Merah","Biru","Hitam"]', 'Biru'),
  (9, 2, 'Bentuk bola adalah?', '["Kotak","Segitiga","Bulat","Persegi"]', 'Bulat'),
  (9, 3, 'Campuran warna merah dan kuning menghasilkan?', '["Ungu","Hijau","Oranye","Coklat"]', 'Oranye'),
  (10, 1, 'Ada berapa hari dalam satu minggu?', '["5","6","7","10"]', '7'),
  (10, 2, 'Hari setelah Senin adalah?', '["Rabu","Selasa","Minggu","Jumat"]', 'Selasa'),
  (10, 3, 'Apa nama planet tempat kita tinggal?', '["Mars","Bulan","Bumi","Matahari"]', 'Bumi')
) AS v(module_id, sort_order, question, options, answer)
WHERE NOT EXISTS (SELECT 1 FROM public.quiz_questions);

ON CONFLICT (slug) DO NOTHING;

ON CONFLICT (category, slug) DO NOTHING;
